  "code": """"LightGBM baseline with target encoding for high-cardinality categoricals."""

from __future__ import annotations

import pandas as pd
from lightgbm import LGBMClassifier


def fit_predict(train_csv: str, test_rows: list[dict[str, str]]) -> list[float]:
    train = pd.read_csv(train_csv)
    y = train.pop("y").astype(int)

    # High-cardinality categorical features for target encoding
    target_encode_cols = ["native_country", "workclass", "occupation"]

    # Compute modes from training data for missing value filling
    train_modes = {}
    for col in train.columns:
        if train[col].isna().any():
            mode_vals = train[col].mode()
            train_modes[col] = mode_vals[0] if len(mode_vals) > 0 else ""
        else:
            train_modes[col] = None

    # Fill missing values in training data with modes
    for col, mode_val in train_modes.items():
        if mode_val is not None:
            train[col] = train[col].fillna(mode_val)

    # Compute target encoding from training data only (prevents leakage)
    encodings = {}
    for col in target_encode_cols:
        encodings[col] = train.groupby(col)[y].mean().to_dict()

    global_mean = y.mean()

    # Apply target encoding to training data
    for col in target_encode_cols:
        train[col] = train[col].map(encodings[col]).fillna(global_mean).astype(float)

    # Prepare test data
    test = pd.DataFrame(test_rows)

    # Fill missing values in test with training modes
    for col in train.columns:
        mode_val = train_modes.get(col)
        if mode_val is not None and test[col].isna().any():
            test[col] = test[col].fillna(mode_val)

    # Apply target encoding to test data
    for col in target_encode_cols:
        test[col] = test[col].map(encodings[col]).fillna(global_mean).astype(float)

    # Convert numeric columns in test data
    for col in train.columns:
        if col not in target_encode_cols:
            try:
                test[col] = pd.to_numeric(test[col], errors='coerce')
            except Exception:
                pass

    # Fit LightGBM model
    model = LGBMClassifier(random_state=20261114, n_jobs=1, verbosity=-1)
    model.fit(train, y)

    # Predict probabilities
    return model.predict_proba(test)[:, 1].tolist()
